// demos/tidelight/gen-assets.ts — the game's content pipeline: every backdrop
// and portrait is generated by the PixelLab pixel-art API (pixellab.ai) from
// the seeded manifest below, then normalized into the pak-safe PNG subset.
//
//   bun demos/tidelight/gen-assets.ts             # generate missing assets
//   bun demos/tidelight/gen-assets.ts --force     # regenerate everything
//   bun demos/tidelight/gen-assets.ts --only=face-maren.png
//
// Auth: PIXELLAB_API_KEY in the repo root .env (Bun auto-loads .env from the
// cwd; the manual parse below keeps the script cwd-independent). Every entry
// pins a `seed` — PixelLab derives its starting noise from it, so a re-run
// reproduces the same art. Generated files are committed; existing files are
// skipped, which makes the script a cheap no-op unless you delete an asset or
// pass --force.
//
// Portrait "state" variants (WICK's alert eye, Maren by the fire) are made
// with init_image + a shifted description, so a character keeps its identity
// across moods — the same trick at generation time that Detroit-style story
// UIs pull off with actor performances.
//
// Output discipline: PixelLab answers 8-bit RGBA non-interlaced PNGs, which
// compiler/pak.ts decodePng already accepts — but we still decode + re-encode
// through the exact canonical subset the gallery baker writes (colorType 6,
// bit depth 8, filter 0, single node:zlib IDAT) so the committed bytes are
// deterministic and the pak build can never hit an exotic encoder feature.
// Texture sizes are pow2 (256x128 scenes, 64x64 portraits) per DESIGN.md.

import { existsSync } from "node:fs";
import { deflateSync } from "node:zlib";
import { decodePng } from "../../compiler/pak.ts";

const HERE = new URL(".", import.meta.url).pathname; // demos/tidelight/
const ROOT = new URL("../..", import.meta.url).pathname; // PocketJS/
const API = "https://api.pixellab.ai/v1";

// ---------------------------------------------------------------------------
// The manifest — one entry per committed asset
// ---------------------------------------------------------------------------

interface Asset {
  name: string;
  prompt: string;
  w: number;
  h: number;
  seed: number;
  /** Transparent background (portraits). */
  transparent?: boolean;
  outline?: string;
  shading?: string;
  detail?: string;
  /** Derive from a previously generated asset (identity-preserving variant). */
  initFrom?: string;
  /** init_image influence 1..999 (PixelLab default 300). */
  initStrength?: number;
}

